begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('99999999-9999-4999-8999-999999999999','search-alice@example.test'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','search-bob@example.test');
set local role anon;
select throws_ok($$select public.search_idea_projects('solar')$$,'42501',null,'Anonymous search denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"99999999-9999-4999-8999-999999999999","role":"authenticated"}',true);
select set_config('test.solar1',public.create_idea_project('{"title":"Solar system"}','search-create-key-01')::text,true);
select set_config('test.solar2',public.create_idea_project('{"title":"SOLAR wind"}','search-create-key-02')::text,true);
select set_config('test.ocean',public.create_idea_project('{"title":"Ocean currents","brief":"solar is only in body"}','search-create-key-03')::text,true);
select set_config('test.literal',public.create_idea_project(jsonb_build_object('title','100% real_under'||chr(92)||'score'),'search-create-key-04')::text,true);
select set_config('test.unicode',public.create_idea_project('{"title":"Écho 🌙"}','search-create-key-05')::text,true);
select is(jsonb_array_length(public.search_idea_projects('sOlAr')),2,'Case-insensitive title substring search');
select is(jsonb_array_length(public.search_idea_projects('  solar  ')),2,'Outer spaces trimmed');
select is(jsonb_array_length(public.search_idea_projects('system')),1,'Substring within title matches');
select is(jsonb_array_length(public.search_idea_projects('body')),0,'Idea body is not searched');
select is(jsonb_array_length(public.search_idea_projects('%')),1,'Percent is literal');
select is(jsonb_array_length(public.search_idea_projects('_')),1,'Underscore is literal');
select is(jsonb_array_length(public.search_idea_projects(chr(92))),1,'Backslash is literal');
select is(jsonb_array_length(public.search_idea_projects($q$' OR 1=1 --$q$)),0,'SQL-looking input is literal');
select is(jsonb_array_length(public.search_idea_projects('ÉCHO')),1,'Unicode case search');
select is(jsonb_array_length(public.search_idea_projects('🌙')),1,'Emoji substring search');
select set_config('test.first', (public.search_idea_projects('solar',false,1)->0)::text,true);
select set_config('test.second',(public.search_idea_projects('solar',false,1,(current_setting('test.first')::jsonb->>'updatedAt')::timestamptz,(current_setting('test.first')::jsonb->>'id')::uuid)->0)::text,true);
select ok((current_setting('test.second')::jsonb->>'id') is not null,'Cursor returns another matching row');
select isnt(current_setting('test.first')::jsonb->>'id',current_setting('test.second')::jsonb->>'id','Matching pages do not overlap');
select throws_ok($$select public.search_idea_projects(null)$$,'P0001','VALIDATION_FAILED','Null search rejected');
select throws_ok($$select public.search_idea_projects(repeat('x',141))$$,'P0001','VALIDATION_FAILED','Long query rejected');
select throws_ok($$select public.search_idea_projects(E'bad\nquery')$$,'P0001','VALIDATION_FAILED','Control characters rejected');
select throws_ok($$select public.search_idea_projects('solar',null)$$,'P0001','VALIDATION_FAILED','Null view rejected');
select throws_ok($$select public.search_idea_projects('solar',false,52)$$,'P0001','VALIDATION_FAILED','Page size bounded');
select throws_ok($$select public.search_idea_projects('solar',false,1,now(),null)$$,'P0001','VALIDATION_FAILED','Partial cursor rejected');
select set_config('test.trash',public.trash_idea_project((current_setting('test.solar2')::jsonb->>'id')::uuid,'{"expectedRevision":1}','search-trash-key-001')::text,true);
select is(jsonb_array_length(public.search_idea_projects('solar')),1,'Active search excludes Trash');
select is(jsonb_array_length(public.search_idea_projects('solar',true)),1,'Trash search includes matching owned summaries');
select ok(not ((public.search_idea_projects('solar',true)->0)?'brief'),'Trash search does not expose creative body');
select is(jsonb_array_length(public.search_idea_projects('')),4,'Empty query lists owned active drafts');
select is(jsonb_array_length(public.search_idea_projects('  ',true)),1,'Whitespace query lists owned Trash');
select set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
select is(public.search_idea_projects('solar'),'[]'::jsonb,'Another owner cannot search these active drafts');
select is(public.search_idea_projects('solar',true),'[]'::jsonb,'Another owner cannot search this Trash');
select set_config('test.bob',public.create_idea_project('{"title":"Solar from Bob"}','search-bob-create01')::text,true);
select is(jsonb_array_length(public.search_idea_projects('solar')),1,'Second owner sees only their matching draft');
select set_config('request.jwt.claims','{"sub":"99999999-9999-4999-8999-999999999999","role":"authenticated"}',true);
select set_config('test.renamed',public.save_idea_project((current_setting('test.solar1')::jsonb->>'id')::uuid,'{"expectedRevision":1,"title":"Lunar system"}','search-rename-key01')::text,true);
select is(jsonb_array_length(public.search_idea_projects('solar')),0,'Rename removes old title match');
select is(jsonb_array_length(public.search_idea_projects('lunar')),1,'Rename adds new title match');
select set_config('test.restored',public.restore_idea_project((current_setting('test.solar2')::jsonb->>'id')::uuid,'{"expectedRevision":2}','search-restore-key1')::text,true);
select is(jsonb_array_length(public.search_idea_projects('solar')),1,'Restoration moves match to active search');
select is(jsonb_array_length(public.search_idea_projects('solar',true)),0,'Restoration removes Trash search match');
reset role;
update public.profiles set deletion_status='pending' where owner_id='99999999-9999-4999-8999-999999999999';
set local role authenticated;
select throws_ok($$select public.search_idea_projects('solar')$$,'P0001','ACCOUNT_UNAVAILABLE','Inactive owner cannot search active drafts');
select throws_ok($$select public.search_idea_projects('solar',true)$$,'P0001','ACCOUNT_UNAVAILABLE','Inactive owner cannot search Trash');
select * from finish();
rollback;
